// ============================================================
// DER EINE AUSGANG
//
// Alle Wege der Verarbeitung muenden hier: eingelesen, unveraendert,
// geloescht, zurueckgestellt, uebersprungen, fehlgeschlagen. Frueher
// sprangen vier verschiedene Enden zurueck in die Schleife des
// Scanners; die Steuerung liest jetzt genau eine Antwortform.
// ============================================================
const e = $input.first().json || {};

let auftrag = {};
try { auftrag = $('Auftrag pruefen').first().json || {}; } catch (err) {}

const roh = String(e.status || '');

let status = 'fehler';
if (roh === 'DONE_INSERTED' || roh === 'DONE_UPDATED') status = 'eingelesen';
else if (roh === 'DONE_NO_CHANGE') status = 'unveraendert';
else if (roh === 'DONE_DELETED') status = 'geloescht';
else if (roh.indexOf('DEFERRED_') === 0) status = 'zurueckgestellt';
else if (roh.indexOf('SKIPPED_') === 0) status = 'uebersprungen';
else if (e._uebersprungen) status = 'uebersprungen';

const grund = e._uebersprungen
  || e.error_code
  || e.rebuild_reason
  || roh
  || null;

return [{ json: {
  status,
  doc_id: e.doc_id || auftrag.doc_id || null,
  filename: e.filename || auftrag.filename || null,
  aktion: auftrag.aktion || null,
  grund,
  chunks: Number(e.expected_chunk_count || e.deleted_chunk_count || 0),
  bilder: Number(e.image_count || 0),
  woerter: Number(e.word_count || 0),
  lauf_id: auftrag.lauf_id || null,
  auftrag_grund: auftrag.grund || null,

  // Arbeitsmappen: welche Blaetter als Tabelle und welche als Text
  // gelesen wurden, damit die Laufbilanz es ausweisen kann.
  blaetter_tabelle: e._blaetter_tabelle || null,
  blaetter_text: e._blaetter_text || null,
  hinweise: e._hinweise || null,

  roh_status: roh || null,
  fertig_am: e.finished_at || new Date().toISOString()
} }];

// ============================================================
// VORGABEN DER VERARBEITUNG
// Alles, was nicht vom einzelnen Auftrag abhaengt: Chunkgroesse,
// Modelle, Speicherort - und das Formatwissen, welche Endung ueber
// die PDF-Wandlung und welche ueber die Workbook-API laeuft.
// Frueher hiess dieser Knoten Config.
// ============================================================
const config = {
  flowVersion: 'sharepoint-verarbeitung-v1',
  embeddingModel: 'text-embedding-3-small',
  embeddingDimensions: 1536,
  chunkSize: 1600,
  chunkOverlap: 200,
  embeddingBatchSize: 50,
  mistralModel: 'mistral-ocr-latest',
  storageBucket: 'rag',
  storagePublicBase: 'https://zckaxkpycyyxaymmkmvu.supabase.co/storage/v1/object/public/rag/',
  defaultAudience: 'public',
  minBodyLength: 20,
  sharePointSiteUrl: 'https://rwgrheinland.sharepoint.com/sites/rwgintranet',

  // Word und PowerPoint laesst Graph selbst nach PDF wandeln - sie
  // laufen dann durch dieselbe OCR-Strecke wie die PDFs.
  ueberPdf: ['docx', 'doc', 'pptx', 'ppt'],

  // Arbeitsmappen ueber die Workbook-API, weil der Extract-Node nur
  // ein Blatt kennt und die uebrigen lautlos weglaesst.
  ueberWorkbook: ['xlsx', 'xlsm'],

  maxZeilenJeBlatt: 5000
};

return $input.all().map(item => ({
  json: { ...item.json, _config: config },
  binary: item.binary
}));

// ============================================================
// DER AUFTRAG
//
// Ein Objekt je Datei, gebaut von der Steuerung. Nichts Binaeres
// ueberquert die Flowgrenze - die Datei wird hier beschafft, nicht
// uebergeben. Das ersetzt Normalize SharePoint Event und den
// groessten Teil von Normalize SharePoint Input: Beide mussten ein
// Dutzend Feldnamen erraten, weil Power Automate sie unterschiedlich
// schrieb. Der Vertrag kennt genau einen Namen je Feld.
// ============================================================
const a = $input.first().json || {};
const cfg = a._config || {};

function txt(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s ? s : null;
}

const aktion = String(a.aktion || '').trim().toLowerCase();
if (aktion !== 'einlesen' && aktion !== 'loeschen') {
  throw new Error('AUFTRAG_AKTION_UNGUELTIG: ' + (a.aktion || '(leer)'));
}

const item_id = txt(a.item_id);
if (!item_id) throw new Error('AUFTRAG_ITEM_ID_FEHLT');

const drive_id = txt(a.drive_id);
if (!drive_id && aktion === 'einlesen') throw new Error('AUFTRAG_DRIVE_ID_FEHLT: ' + item_id);

const filename = txt(a.filename) || 'unbenannt';
const endung = String(txt(a.endung) || filename.split('.').pop() || '').toLowerCase();

const ueberPdf = new Set(cfg.ueberPdf || []);
const ueberWorkbook = new Set(cfg.ueberWorkbook || []);

// Laesst Graph die Datei nach PDF wandeln, ist der Inhalt ein PDF -
// unabhaengig davon, was der Dateiname sagt. Frueher wurde das an den
// ersten Base64-Zeichen erraten; hier ist es bekannt.
const als_pdf = aktion === 'einlesen' && ueberPdf.has(endung);
const als_mappe = aktion === 'einlesen' && ueberWorkbook.has(endung);
const ext = als_pdf ? 'pdf' : endung;

const mimeByExt = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  doc: 'application/msword',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  ppt: 'application/vnd.ms-powerpoint',
  csv: 'text/csv',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xlsm: 'application/vnd.ms-excel.sheet.macroEnabled.12',
  ods: 'application/vnd.oasis.opendocument.spreadsheet',
  txt: 'text/plain', md: 'text/markdown', markdown: 'text/markdown', log: 'text/plain',
  json: 'application/json', xml: 'application/xml', html: 'text/html', htm: 'text/html',
  ics: 'text/calendar', rtf: 'application/rtf',
  png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg',
  tif: 'image/tiff', tiff: 'image/tiff', webp: 'image/webp', avif: 'image/avif'
};

const documentAi = new Set(['pdf', 'docx', 'pptx', 'doc', 'ppt', 'png', 'jpg', 'jpeg', 'tif', 'tiff', 'webp', 'avif']);
const spreadsheet = new Set(['csv', 'xls', 'xlsx', 'xlsm', 'ods']);
const textLike = new Set(['txt', 'md', 'markdown', 'log', 'json', 'xml', 'html', 'htm', 'ics', 'rtf']);

let route_group = 'unsupported';
if (als_mappe) route_group = 'spreadsheet';
else if (documentAi.has(ext)) route_group = 'document_ai';
else if (spreadsheet.has(ext)) route_group = 'spreadsheet';
else if (textLike.has(ext)) route_group = 'text';

// Drei Wege: ueber den Dateiinhalt, ueber die Workbook-API, oder gar
// nicht, weil geloescht wird.
let weg = 'datei';
if (aktion === 'loeschen') weg = 'loeschen';
else if (als_mappe) weg = 'arbeitsmappe';

const imageExts = new Set(['png', 'jpg', 'jpeg', 'tif', 'tiff', 'webp', 'avif']);

// Die Dokument-URL kommt aus dem Graph-Bestand mit. Fehlt sie, wird
// sie aus Site und Pfad gebaut - ohne sie ist ein Treffer fuer den
// Anwender nicht anklickbar.
function dokumentUrl() {
  const direkt = txt(a.sharepoint_url);
  if (direkt && /^https?:\/\//i.test(direkt)) return { url: direkt, quelle: 'uebergeben' };
  const site = txt(a.site_url) || txt(cfg.sharePointSiteUrl);
  const pfad = txt(a.file_path);
  if (site && pfad) {
    const rein = pfad.replace(/^\/+/, '');
    const kodiert = /%[0-9A-Fa-f]{2}/.test(rein) ? rein : rein.split('/').map(s => encodeURIComponent(s)).join('/');
    return { url: site.replace(/\/+$/, '') + '/' + kodiert, quelle: 'site_und_pfad' };
  }
  return { url: null, quelle: 'nicht_ableitbar' };
}
const url = dokumentUrl();

const erlaubteAudience = new Set(['public', 'it_internal']);
const rohAudience = String(txt(a.audience) || '').toLowerCase();
const audience = erlaubteAudience.has(rohAudience)
  ? rohAudience
  : (erlaubteAudience.has(String(cfg.defaultAudience || '')) ? cfg.defaultAudience : 'it_internal');

return [{ json: {
  aktion,
  weg,

  doc_id: item_id,
  file_id: item_id,
  item_id,
  drive_id,
  site_id: txt(a.site_id),
  site_url: txt(a.site_url) || txt(cfg.sharePointSiteUrl),

  filename,
  title: filename.replace(/\.[^/.]+$/, ''),
  endung,
  ext,
  fileType: ext,
  original_extension: endung,
  als_pdf,
  ueber_pdf_gewandelt: als_pdf,
  mime_type: mimeByExt[ext] || 'application/octet-stream',
  mimeType: mimeByExt[ext] || 'application/octet-stream',
  route_group,
  mistral_document_type: imageExts.has(ext) ? 'image_url' : 'document_url',

  file_path: txt(a.file_path),
  sharepoint_url: url.url,
  sharepoint_url_quelle: url.quelle,
  department: txt(a.department),
  author_name: txt(a.author_name),
  author_email: txt(a.author_email),
  last_modified_by: txt(a.last_modified_by),
  created_at_sp: txt(a.created_at_sp),
  last_modified_sp: txt(a.last_modified_sp),
  document_version: txt(a.etag) || txt(a.document_version),
  bytes: Number(a.bytes || 0),
  tags: Array.isArray(a.tags) ? a.tags : [],
  language: txt(a.language) || 'de',
  sensitivity_label: txt(a.sensitivity_label),
  audience,
  alt_doc_id: txt(a.alt_doc_id),

  grund: txt(a.grund),
  lauf_id: txt(a.lauf_id),
  quelle: txt(a.quelle) || 'steuerung',
  sharepoint_crud_intent: aktion === 'loeschen' ? 'DELETE' : 'UPSERT',

  flow_version: cfg.flowVersion || 'sharepoint-verarbeitung-v1',
  _config: cfg,
  geprueft_am: new Date().toISOString()
} }];

// ============================================================
// METADATEN NEBEN DIE DATEI LEGEN
//
// Der HTTP-Knoten und die Dateiwandlung ersetzen das JSON durch die
// Binaerdaten. Hier kommen die Auftragsdaten wieder daneben.
//
// Beim Arbeitsmappen-Weg gelten die Angaben aus Tabelle als CSV
// bauen: dort heisst die Datei anders und ist eine CSV geworden.
//
// Der Knoten behaelt seinen alten Namen, weil neun Knoten der
// Verarbeitung ihn ueber $('Normalize SharePoint Input') lesen.
//
// FILEBASE64CLEAN
// Der Inhaltshash entscheidet, ob ein Dokument neu aufgebaut wird.
// Gebildet wurde er bisher ueber den Base64-Text der Datei. Wuerde
// hier etwas anderes gehasht, gaelte jedes Dokument im Bestand als
// geaendert und liefe erneut durch die OCR. Der Wert wird deshalb
// aus den Binaerdaten wiederhergestellt - dieselbe Zeichenkette wie
// frueher, nur ohne den Umweg ueber die Flowgrenze.
// ============================================================
let meta = null;
try {
  const m = $('Tabelle als CSV bauen').first().json;
  if (m && m._mappe) meta = m;
} catch (e) {}
if (!meta) meta = $('Auftrag pruefen').first().json;

const rest = Object.assign({}, meta);
delete rest.csv_base64;

let fileBase64Clean = null;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  fileBase64Clean = buf.toString('base64');
} catch (e) {
  throw new Error('DATEI_BINAER_FEHLT: ' + (rest.filename || rest.doc_id || '?'));
}

return $input.all().map(item => ({
  json: Object.assign({}, rest, {
    fileBase64Clean,
    normalized_at: new Date().toISOString()
  }),
  binary: item.binary
}));

// Jedes Blatt wird ein eigenes Item, damit der folgende Abruf je
// Blatt einmal laeuft. Ausgeblendete Blaetter bleiben aussen vor -
// sie sind bewusst versteckt.
const antwort = $input.first().json || {};
const a = $('Auftrag pruefen').first().json;

if (antwort.error || !antwort.value) {
  const grund = antwort.error ? String(antwort.error.message || antwort.error).slice(0, 160) : 'KEINE_ANTWORT';
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: grund, blaetter_gesamt: 0, blatt_index: 0 }) }];
}

const alle = antwort.value || [];
const sichtbar = alle.filter(w => !w.visibility || w.visibility === 'Visible');

if (!sichtbar.length) {
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: 'KEINE_SICHTBAREN_BLAETTER', blaetter_gesamt: 0, blatt_index: 0 }) }];
}

return sichtbar
  .sort((x, y) => Number(x.position || 0) - Number(y.position || 0))
  .map((w, i) => ({ json: Object.assign({}, a, {
    blatt: w.name,
    blatt_index: i,
    blaetter_gesamt: sichtbar.length,
    blaetter_alle: alle.length,
    blatt_fehler: null
  }) }));

// ============================================================
// ARBEITSMAPPE AUFBEREITEN
//
// Nicht jedes Blatt einer Arbeitsmappe ist eine Tabelle. Es gibt
// Deckblaetter, Notizen, ausgefuellte Formulare und Layouts. Wer
// dort blind die erste Zeile als Kopfzeile nimmt, erzeugt Unsinn.
//
// Und selbst echte Tabellen fangen selten in Zeile 1 an. Ueber der
// Kopfzeile stehen Titel, Stand-Angaben oder Leerzeilen. Deshalb
// wird die Kopfzeile in den ersten Zeilen gesucht statt angenommen.
//
// Tabellenblaetter kommen mit ihren echten Spalten, alles andere als
// Text unter Blatt, Zeile und Inhalt. Beides landet in derselben
// CSV, damit eine Datei ein Dokument bleibt.
// ============================================================
const a = $('Auftrag pruefen').first().json;
const cfg = a._config || {};
const maxZeilen = Number(cfg.maxZeilenJeBlatt || 5000);
const SUCHTIEFE = 8;

function text(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function istZahl(v) {
  const s = text(v);
  return s !== '' && !isNaN(Number(s.replace(/\./g, '').replace(',', '.')));
}

function kopfGuete(werte, i) {
  const zeile = werte[i] || [];
  const gefuellt = zeile.filter(c => text(c) !== '');
  if (gefuellt.length < 2) return 0;
  const zahlanteil = gefuellt.filter(istZahl).length / gefuellt.length;
  if (zahlanteil > 0.5) return 0;
  const eindeutig = new Set(gefuellt.map(c => text(c).toLowerCase())).size;
  if (eindeutig < gefuellt.length * 0.8) return 0;
  if (gefuellt.filter(c => text(c).length > 120).length) return 0;
  const probe = werte.slice(i + 1, i + 21);
  if (probe.length < 2) return 0;
  const schnitt = probe.reduce((s, z) => s + z.filter(c => text(c) !== '').length, 0) / probe.length;
  if (schnitt / gefuellt.length < 0.3) return 0;
  return gefuellt.length * Math.min(schnitt / gefuellt.length, 1) * 100 - i;
}

const eingang = $input.all();
const tabellen = [];
const notizen = [];
const hinweise = [];

for (let i = 0; i < eingang.length; i++) {
  const j = eingang[i].json || {};
  const meta = $('Blaetter auffaechern').all()[i];
  const name = (meta && meta.json.blatt) || j.blatt || ('Blatt ' + (i + 1));

  if (meta && meta.json.blatt_fehler) { hinweise.push(name + ': ' + meta.json.blatt_fehler); continue; }
  if (j.error) { hinweise.push(name + ': ' + String(j.error.message || j.error).slice(0, 120)); continue; }

  const alle = Array.isArray(j.values) ? j.values : [];
  const werte = alle.filter(z => z.some(c => text(c) !== ''));
  if (!werte.length) { hinweise.push(name + ': leer'); continue; }
  if (werte.length > maxZeilen + 1) hinweise.push(name + ': auf ' + maxZeilen + ' von ' + (werte.length - 1) + ' Zeilen begrenzt');

  let besteZeile = -1;
  let besteGuete = 0;
  for (let k = 0; k < Math.min(SUCHTIEFE, werte.length - 2); k++) {
    const g = kopfGuete(werte, k);
    if (g > besteGuete) { besteGuete = g; besteZeile = k; }
  }

  if (besteZeile >= 0) {
    const kopf = werte[besteZeile].map((c, k) => text(c) || ('Spalte ' + (k + 1)));
    const davor = werte.slice(0, besteZeile)
      .map((z, k) => ({ nr: k + 1, inhalt: z.map(text).filter(Boolean).join('  |  ') }))
      .filter(z => z.inhalt);
    if (davor.length) notizen.push({ name: name + ' (Kopfbereich)', zeilen: davor });
    if (besteZeile > 0) hinweise.push(name + ': Kopfzeile in Zeile ' + (besteZeile + 1) + ' gefunden');
    tabellen.push({ name, kopf, zeilen: werte.slice(besteZeile + 1, besteZeile + 1 + maxZeilen) });
  } else {
    const zeilen = werte.slice(0, maxZeilen).map((z, k) => ({
      nr: k + 1,
      inhalt: z.map(text).filter(Boolean).join('  |  ')
    })).filter(z => z.inhalt);
    if (zeilen.length) {
      notizen.push({ name, zeilen });
      hinweise.push(name + ': als Text uebernommen, keine Tabellenstruktur erkannt');
    }
  }
}

if (!tabellen.length && !notizen.length) {
  return [{ json: Object.assign({}, a, { _uebersprungen: 'KEINE_BLATTDATEN', _hinweise: hinweise }) }];
}

const spalten = [];
const bekannt = new Set();
for (const b of tabellen) {
  for (const s of b.kopf) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}
if (notizen.length) {
  for (const s of ['Zeile', 'Inhalt']) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}

function feld(v) {
  const t = v === null || v === undefined ? '' : String(v);
  return /[",\n\r]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t;
}

const ausgabe = [['Blatt'].concat(spalten).map(feld).join(',')];
let zeilenTabelle = 0;
let zeilenText = 0;

for (const b of tabellen) {
  const nachSpalte = {};
  b.kopf.forEach((s, k) => { if (nachSpalte[s] === undefined) nachSpalte[s] = k; });
  for (const z of b.zeilen) {
    if (!z.some(c => text(c) !== '')) continue;
    const reihe = [b.name].concat(spalten.map(s => {
      const k = nachSpalte[s];
      return k === undefined ? '' : z[k];
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenTabelle++;
  }
}

for (const b of notizen) {
  for (const z of b.zeilen) {
    const reihe = [b.name].concat(spalten.map(s => {
      if (s === 'Zeile') return z.nr;
      if (s === 'Inhalt') return z.inhalt;
      return '';
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenText++;
  }
}

const csv = ausgabe.join('\n');
const art = tabellen.length && notizen.length ? 'Tabellen und Text'
          : tabellen.length ? 'alle Blaetter'
          : 'als Text';
const basis = String(a.filename || '').replace(/\.[^/.]+$/, '');
const csvName = basis + ' (' + a.endung + ', ' + art + ').csv';

// Ab hier ist das Dokument eine CSV - Name, Endung und Weg werden
// umgestellt, damit die Extraktionsstrecke sie richtig behandelt.
return [{ json: Object.assign({}, a, {
  _mappe: true,
  csv_base64: Buffer.from(csv, 'utf8').toString('base64'),
  filename: csvName,
  title: csvName.replace(/\.[^/.]+$/, ''),
  ext: 'csv',
  fileType: 'csv',
  mime_type: 'text/csv',
  mimeType: 'text/csv',
  route_group: 'spreadsheet',
  ueber_pdf_gewandelt: false,
  _blaetter_tabelle: tabellen.map(b => b.name),
  _blaetter_text: notizen.map(b => b.name),
  _zeilen_tabelle: zeilenTabelle,
  _zeilen_text: zeilenText,
  _hinweise: hinweise
}) }];

const binField = 'data';

// Zeichen 0xFEFF ist die Byte-Order-Mark. Frueher stand hier ein Regex
// mit Unicode-Escape; als Zeichencode-Pruefung ist dasselbe Verhalten
// sichtbar im Code, statt als unsichtbares Zeichen darin zu stehen.
function ohneBom(text) {
  return text.charCodeAt(0) === 0xFEFF ? text.slice(1) : text;
}

function normalizeBuffer(buf) {
  if (buf.length >= 3 && buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) {
    return buf.slice(3);
  }
  if (buf.length >= 2 && buf[0] === 0xFF && buf[1] === 0xFE) {
    return Buffer.from(ohneBom(buf.slice(2).toString('utf16le')), 'utf8');
  }
  if (buf.length >= 2 && buf[0] === 0xFE && buf[1] === 0xFF) {
    const src = buf.slice(2);
    const swapped = Buffer.alloc(src.length);
    for (let i = 0; i + 1 < src.length; i += 2) {
      swapped[i] = src[i + 1];
      swapped[i + 1] = src[i];
    }
    return Buffer.from(ohneBom(swapped.toString('utf16le')), 'utf8');
  }
  return Buffer.from(ohneBom(buf.toString('utf8')), 'utf8');
}

for (let i = 0; i < items.length; i++) {
  const oldBin = items[i].binary?.[binField];
  if (!oldBin) throw new Error('CSV_BINARY_' + binField + '_MISSING');
  const buf = await this.helpers.getBinaryDataBuffer(i, binField);
  const cleaned = normalizeBuffer(buf);
  items[i].binary[binField] = await this.helpers.prepareBinaryData(
    cleaned,
    oldBin.fileName || 'file.csv',
    'text/csv'
  );
}
return items;

const input = $('Normalize SharePoint Input').first().json;
const rows = $input.all().map(item => item.json || {});
const schema = Array.from(new Set(
  rows.flatMap(row => Object.keys(row).map(key => key.trim()).filter(Boolean))
));

function printable(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try { return JSON.stringify(value); } catch { return String(value); }
}

const header = [
  '[SHAREPOINT-TABELLE] ' + input.filename,
  'Dokument-ID: ' + input.doc_id,
  'Format: ' + String(input.ext).toUpperCase(),
  'Zeilen: ' + rows.length,
  'Spalten: ' + (schema.join(', ') || '[keine]'),
  input.file_path ? 'Pfad: ' + input.file_path : '',
  input.department ? 'Bereich: ' + input.department : '',
  input.sharepoint_url ? 'SharePoint-URL: ' + input.sharepoint_url : ''
].filter(Boolean).join('\n');

const rowText = rows.map((row, index) => {
  const fields = schema
    .map(key => {
      const value = printable(row[key]);
      return value ? '- ' + key + ': ' + value : '';
    })
    .filter(Boolean)
    .join('\n');
  return '### Zeile ' + (index + 1) + '\n' + (fields || '- [Leere Zeile]');
}).join('\n\n');

const body_length = rowText.trim().length;
