// Zeichen 0xFEFF ist die Byte-Order-Mark. Frueher stand hier ein Regex
// mit Unicode-Escape; als Zeichencode-Pruefung ist dasselbe Verhalten
// sichtbar im Code, statt als unsichtbares Zeichen darin zu stehen.
function ohneBom(text) {
  return text.charCodeAt(0) === 0xFEFF ? text.slice(1) : text;
}

function decode(buffer) {
  if (buffer.length >= 3 && buffer[0] === 0xEF && buffer[1] === 0xBB && buffer[2] === 0xBF) {
    return buffer.slice(3).toString('utf8');
  }
  if (buffer.length >= 2 && buffer[0] === 0xFF && buffer[1] === 0xFE) {
    return ohneBom(buffer.slice(2).toString('utf16le'));
  }
  if (buffer.length >= 2 && buffer[0] === 0xFE && buffer[1] === 0xFF) {
    const src = buffer.slice(2);
    const swapped = Buffer.alloc(src.length);
    for (let i = 0; i + 1 < src.length; i += 2) {
      swapped[i] = src[i + 1];
      swapped[i + 1] = src[i];
    }
    return ohneBom(swapped.toString('utf16le'));
  }
  return ohneBom(buffer.toString('utf8'));
